[
  {
    "qid": "0006-t2i-1",
    "sample_id": "0006_雨、蒸汽和速度（透纳）_afb6a511.jpg",
    "task": "t2i",
    "knowledge_dim": "art_style",
    "difficulty": "L2",
    "evidence_audit": {
      "visible_facts": [
        "原画展现了蒸汽机车、铁轨桥梁与雨雾水面交融的场景",
        "笔触粗犷厚重，物体轮廓被强烈的大气光影模糊消融",
        "色调由中心耀眼的金黄/淡黄色向周围的暴风雨冷灰、蓝褐渐变扩散",
        "构图具有强烈的透视动势与工业机械动力的速度感"
      ],
      "anchor_features": [
        "英国浪漫主义风景画大师J.M.W.透纳晚期标志性的光与大气氛围（Sublime）",
        "旋涡状/厚涂的大气光雾将物体与自然背景融为一体",
        "工业文明产物与狂暴自然力量的浪漫主义并置"
      ],
      "trigger_check": "非目标模型若仅理解字面描述，会画成写实具象的古典油画或现代数码暴风雨CG；只有掌握透纳晚期油画风格知识的模型才能正确呈现消融轮廓的光雾旋涡与特征色彩搭配。",
      "counterexample_test": "无法在符合透纳晚期风格的前提下构造出轮廓锐利、工笔写实、色调均匀平淡的画面。"
    },
    "gen_prompt": "一幅英国浪漫主义大师威廉·透纳晚期风格的布面油画：在狂风暴雨与落日余晖交织的泰晤士河口，一艘19世纪早期的蒸汽机明轮拖船破浪前行，烟囱中涌出滚滚浓烟，整幅画展现工业动力与大自然壮阔力量的交锋。",
    "implicit_checks": [
      {
        "check": "画面呈现透纳晚期典型的大气光雾消融效果，物体形态与背景风暴、水汽融为一体，轮廓模糊写意而非清晰勾勒",
        "knowledge": "[solid] 透纳晚期画风以光和大气（Light and Atmosphere）为核心，物象轮廓高度消融于旋涡状的烟雾与风暴笔触中",
        "verified": true,
        "weight": 0.4,
        "rubric": {
          "0": "物体轮廓极其锐利工整，呈现清晰的写实写生或现代数码插画感，无透纳式光雾消融效果",
          "1": "有一定烟雾或水汽，但船只或水面仍保留明显的边缘线条，笔触未形成浑然一体的氛围感",
          "2": "船身、蒸汽与风暴水气在粗犷笔触下高度交融，呈现典型的光与大气的写意消融特征"
        },
        "acceptable_variants": [
          "船体局部细节略显清晰但整体仍被剧烈光雾笼罩",
          "厚重油画肌理形成的斑驳轮廓"
        ]
      },
      {
        "check": "画面主色调呈现透纳晚期特征性的高对比色调，以明亮的金黄/暖白光芒与暴风雨的冷灰/靛蓝/暗赭形成强烈对冲",
        "knowledge": "[solid] 透纳晚期色彩体系极具辨识度，惯用刺眼的金黄、柠檬黄光晕撕裂灰暗风暴的冷色调空间",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "色调单调灰暗无明显高光，或采用非透纳风格的艳丽糖果色、现代高饱和度霓虹色彩",
          "1": "包含暖光与暗云，但光暗对比平淡，缺乏透纳式的中心光爆或冷暖交织的戏剧性张力",
          "2": "画面具有醒目的金黄/明亮暖色光辉与阴沉暴风雨冷灰蓝褐的强烈对比，光感极具穿透力"
        },
        "acceptable_variants": [
          "光芒集中在天空正中向四周辐射",
          "落日金光自侧向撕裂暴风雨阴云"
        ]
      },
      {
        "check": "主体船舶符合19世纪早期工业革命特征（如明轮结构、细长直立烟囱），并伴随明显的黑灰色蒸汽烟雾",
        "knowledge": "[solid] 19世纪前半叶工业革命初期的蒸汽船多采用侧舷明轮（Paddle steamer）及高细烟囱设计",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "画成纯现代柴油机货轮、未来科幻船只或无任何机械动力特征的普通古代木帆船",
          "1": "画有现代轮船外观仅简单加装烟囱，或早期工业蒸汽机械特征模糊不明确",
          "2": "准确呈现早期蒸汽船形态（可见细长烟囱并喷吐浓厚烟雾，且具备早期木质/明轮船体结构特征）"
        },
        "acceptable_variants": [
          "明轮被浪花半遮挡但可见侧舷轮罩结构",
          "船体带有早期混合动力特征（蒸汽烟囱辅以部分桅杆）"
        ]
      }
    ],
    "facet_tags": [
      "style_control",
      "lighting_atmosphere",
      "material_texture",
      "temporal_characteristics"
    ],
    "gate_spec": {
      "required_subjects": [
        "蒸汽船",
        "暴风雨水面"
      ],
      "theme_definition": "威廉·透纳晚期浪漫主义风格的暴风雨蒸汽船舶油画"
    },
    "expected_failure_modes": [
      "画成工整清晰的超写实古典海战油画，轮廓边缘锐利，缺乏透纳的写意光雾感",
      "画成现代数码概念插画风格，色彩平滑油腻，无油画笔触厚涂与飞白肌理",
      "画成现代钢制集装箱船或纯木质帆船，忽略19世纪早期工业蒸汽船形制"
    ],
    "notes": "考察透纳晚期画风（光气消融、戏剧性金灰冷暖光影、厚重笔触）与19世纪工业革命蒸汽机械特征的整合表现。"
  }
]
